), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj || ' ' || CASE WHEN s.k = 1 THEN i.one ELSE replace(i.many, '{k}', s.k::text) END)
       FROM tpl t JOIN ind i USING (lang) WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
INSERT INTO public.training_sessions (name, info, objectif, session_json, total_duration, is_test, live_comments, translations_json, aero_duration_sec)
SELECT b.skey || '_name', b.skey || '_info', b.skey || '_objectif',
  jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  b.minutes, false, b.lc,
  jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"endurance_tt_8w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "endurance_tt_8w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "endurance_tt_8w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "endurance_tt_8w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  b.aero
FROM built b
WHERE NOT EXISTS (SELECT 1 FROM public.training_sessions ts WHERE ts.name = b.skey || '_name');

INSERT INTO public.training_plans (name_key, description_key, objective_key, duration_weeks, difficulty, plan_type, sessions_per_week, is_active, translations_json)
SELECT 'endurance_tt_8w_name', 'endurance_tt_8w_description', 'endurance_tt_8w_objective', 8, 'intermediate', 'training', 4, true, '{"name": {"fr": "Endurance aéro 8 semaines : jusqu''à 90'' en TT", "en": "8-week aero endurance: up to 90'' in TT", "es": "Resistencia aero 8 semanas: hasta 90'' en TT", "it": "Resistenza aero 8 settimane: fino a 90'' in TT", "de": "8 Wochen Aero-Ausdauer: bis 90'' in TT", "nl": "8 weken aero-duur: tot 90'' in TT", "pt": "Resistência aero 8 semanas: até 90'' em TT", "ja": "8週間エアロ持久：TTで最大90分", "tr": "8 haftalık aero dayanıklılık: TT''de 90''a kadar"}, "objective": {"fr": "Tenir la position TT 90 minutes d''affilée en endurance et 2×30'' au tempo, la base d''un triathlon longue distance.", "en": "Hold the TT position for 90 minutes in a row at endurance pace and 2×30'' at tempo, the foundation for long-distance triathlon.", "es": "Mantener la posición TT 90 minutos seguidos en resistencia y 2×30'' a tempo, la base de un triatlón de larga distancia.", "it": "Tenere la posizione TT 90 minuti di fila in resistenza e 2×30'' a ritmo tempo, la base di un triathlon lungo.", "de": "Die TT-Position 90 Minuten am Stück im Grundlagentempo und 2×30'' im Tempo halten, die Basis für die Triathlon-Langdistanz.", "nl": "De TT-houding 90 minuten aan één stuk op duurtempo en 2×30'' op tempo vasthouden, de basis voor lange-afstandstriatlon.", "pt": "Manter a posição TT 90 minutos seguidos em resistência e 2×30'' em ritmo tempo, a base de um triatlo de longa distância.", "ja": "持久ペースで90分連続、テンポで2×30''のTTを保つ。ロングディスタンス・トライアスロンの土台。", "tr": "TT pozisyonunu dayanıklılık temposunda aralıksız 90 dakika ve tempoda 2×30'' koru; uzun mesafe triatlonun temeli."}, "description": {"fr": "8 semaines en deux cycles de 3 semaines de charge et 1 semaine allégée, 3 à 4 séances de 50 minutes à 2 h 50. Endurance TT en blocs de 20 à 75 minutes, tempo de 10 à 30 minutes, une sortie longue par semaine jusqu''à 2 h 35. Chaque séance fixe un nombre de passages en TT à valider.", "en": "8 weeks in two cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 50 minutes to 2 h 50. TT endurance in 20 to 75 minute blocks, tempo from 10 to 30 minutes, one long ride a week up to 2 h 35. Each session sets a number of TT blocks to validate.", "es": "8 semanas en dos ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 50 minutos a 2 h 50. Resistencia TT en bloques de 20 a 75 minutos, tempo de 10 a 30 minutos, una salida larga por semana hasta 2 h 35. Cada sesión fija un número de tramos en TT a validar.", "it": "8 settimane in due cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 50 minuti a 2 h 50. Resistenza TT in blocchi da 20 a 75 minuti, tempo da 10 a 30 minuti, un''uscita lunga a settimana fino a 2 h 35. Ogni sessione fissa un numero di tratti in TT da validare.", "de": "8 Wochen in zwei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 50 Minuten bis 2 h 50. TT-Ausdauer in Blöcken von 20 bis 75 Minuten, Tempo von 10 bis 30 Minuten, eine lange Fahrt pro Woche bis 2 h 35. Jede Einheit legt eine Anzahl zu bestehender TT-Abschnitte fest.", "nl": "8 weken in twee cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 50 minuten tot 2 u 50. TT-duur in blokken van 20 tot 75 minuten, tempo van 10 tot 30 minuten, één lange rit per week tot 2 u 35. Elke sessie legt een aantal te halen TT-stukken vast.", "pt": "8 semanas em dois ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 50 minutos a 2 h 50. Resistência TT em blocos de 20 a 75 minutos, tempo de 10 a 30 minutos, um treino longo por semana até 2 h 35. Cada sessão fixa um número de trechos em TT a validar.", "ja": "8週間を、負荷3週＋軽め1週の2サイクルで。50分〜2時間50分のセッションを週3〜4回。TT持久は20〜75分のブロック、テンポは10〜30分、週1回のロングライドは最大2時間35分。各セッションで達成すべきTTブロック数を設定。", "tr": "8 hafta, 3 yüklenme haftası + 1 hafif haftadan oluşan iki döngü, haftada 50 dakika ile 2 sa 50 arası 3-4 seans. 20-75 dakikalık bloklarda TT dayanıklılığı, 10-30 dakika tempo, haftada bir 2 sa 35''e kadar uzun sürüş. Her seans onaylanacak TT bölümü sayısını belirler."}}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM public.training_plans WHERE name_key = 'endurance_tt_8w_name');

INSERT INTO public.plan_sessions (plan_id, training_session_id, week_number, session_number)
SELECT p.id, ts.id, v.week, v.num
FROM (VALUES (1, 1, 'endurance_tt_8w_w1s1_name'), (1, 2, 'endurance_tt_8w_w1s2_name'), (1, 3, 'endurance_tt_8w_w1s3_name'), (1, 4, 'endurance_tt_8w_w1s4_name'), (2, 1, 'endurance_tt_8w_w2s1_name'), (2, 2, 'endurance_tt_8w_w2s2_name'), (2, 3, 'endurance_tt_8w_w2s3_name'), (2, 4, 'endurance_tt_8w_w2s4_name'), (3, 1, 'endurance_tt_8w_w3s1_name'), (3, 2, 'endurance_tt_8w_w3s2_name'), (3, 3, 'endurance_tt_8w_w3s3_name'), (3, 4, 'endurance_tt_8w_w3s4_name'), (4, 1, 'endurance_tt_8w_w4s1_name'), (4, 2, 'endurance_tt_8w_w4s2_name'), (4, 3, 'endurance_tt_8w_w4s3_name'), (5, 1, 'endurance_tt_8w_w5s1_name'), (5, 2, 'endurance_tt_8w_w5s2_name'), (5, 3, 'endurance_tt_8w_w5s3_name'), (5, 4, 'endurance_tt_8w_w5s4_name'), (6, 1, 'endurance_tt_8w_w6s1_name'), (6, 2, 'endurance_tt_8w_w6s2_name'), (6, 3, 'endurance_tt_8w_w6s3_name'), (6, 4, 'endurance_tt_8w_w6s4_name'), (7, 1, 'endurance_tt_8w_w7s1_name'), (7, 2, 'endurance_tt_8w_w7s2_name'), (7, 3, 'endurance_tt_8w_w7s3_name'), (7, 4, 'endurance_tt_8w_w7s4_name'), (8, 1, 'endurance_tt_8w_w8s1_name'), (8, 2, 'endurance_tt_8w_w8s2_name'), (8, 3, 'endurance_tt_8w_w8s3_name')) AS v(week, num, session_name)
JOIN public.training_sessions ts ON ts.name = v.session_name
JOIN public.training_plans p ON p.name_key = 'endurance_tt_8w_name'
WHERE NOT EXISTS (SELECT 1 FROM public.plan_sessions ps WHERE ps.plan_id = p.id AND ps.training_session_id = ts.id);
